//! Linux compilation symbols generated by Unity rather than stored in project settings.
//! Shared build capabilities were checked against the recorded 2022.3 and 6000.3 editors.
use super::{Platform, UnityVersion};
use std::collections::BTreeSet;

pub(super) fn symbols(
    version: UnityVersion,
    platform: Platform,
    api: u32,
    editor_only: bool,
) -> BTreeSet<String> {
    let mut result = BTreeSet::new();
    let mut add = |words: &str| result.extend(words.split_whitespace().map(str::to_owned));
    add(COMMON);
    add(if version.branch.major == 2022 {
        UNITY_2022
    } else {
        UNITY_6
    });
    add(if api == 6 {
        "NETSTANDARD NETSTANDARD2_1 NET_STANDARD NET_STANDARD_2_0 NET_STANDARD_2_1"
    } else {
        "NET_4_6 NET_UNITY_4_8"
    });
    if platform == Platform::EditorLinux {
        add(
            "DEBUG TRACE ENABLE_BURST_AOT ENABLE_PROFILER ENABLE_UNITY_COLLECTIONS_CHECKS UNITY_ASSERTIONS UNITY_EDITOR UNITY_EDITOR_64 UNITY_EDITOR_LINUX UNITY_TEAM_LICENSE",
        );
    }
    if editor_only {
        add("UNITY_EDITOR_ONLY_COMPILATION");
    }
    // Unity's historical symbol sequence, including 2023.3 (renamed Unity 6).
    for (major, first, last) in [
        (5, 3, 6),
        (2017, 1, 4),
        (2018, 1, 4),
        (2019, 1, 4),
        (2020, 1, 3),
        (2021, 1, 3),
        (2022, 1, 3),
        (2023, 1, 3),
        (6000, 0, 3),
    ] {
        for minor in first..=last {
            if (major, minor) <= (version.branch.major, version.branch.minor) {
                result.insert(format!("UNITY_{major}_{minor}_OR_NEWER"));
            }
        }
    }
    result
}

